import type { Metadata } from "next";
import { SITE_NAME, SITE_URL, TAGLINE } from "@/lib/site";

// Shared social card generated by app/opengraph-image.tsx. Page-level
// `openGraph` objects REPLACE the root layout's (no deep merge), so any page
// that sets its own openGraph must re-supply url/images or it ships without
// og:image / og:url / twitter:image.
export const DEFAULT_OG_IMAGE = {
  url: `${SITE_URL}/opengraph-image`,
  width: 1200,
  height: 630,
  alt: `${SITE_NAME} — ${TAGLINE}`,
};

/** Full metadata for an indexable page: canonical, Open Graph, Twitter. */
export function pageMetadata({
  title,
  description,
  path,
}: {
  title: string;
  description: string;
  /** Route path beginning with "/". */
  path: string;
}): Metadata {
  const url = `${SITE_URL}${path}`;
  return {
    title,
    description,
    alternates: { canonical: url },
    openGraph: {
      title,
      description,
      url,
      siteName: SITE_NAME,
      type: "website",
      images: [DEFAULT_OG_IMAGE],
    },
    twitter: {
      card: "summary_large_image",
      title,
      description,
      images: [DEFAULT_OG_IMAGE],
    },
  };
}
